BEGIN TRANSACTION READ ONLY;
SELECT 'auth_columns' AS section,jsonb_agg(jsonb_build_object('column',column_name,'type',data_type) ORDER BY ordinal_position) AS evidence FROM information_schema.columns WHERE table_schema='auth' AND table_name='users' AND column_name IN ('id','email','raw_app_meta_data','raw_user_meta_data')
UNION ALL SELECT 'dependencies',jsonb_agg(jsonb_build_object('name',p.proname,'security_definer',p.prosecdef,'settings',p.proconfig,'body_md5',md5(regexp_replace(p.prosrc,'\s+','','g')),'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_role_execute',has_function_privilege('service_role',p.oid,'EXECUTE'))) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('bedos_authorize_staff_invitation','bedos_prepare_staff_invitation_retry','bedos_finish_staff_invitation_retry','bedos_record_staff_invitation_password_baseline','bedos_activate_staff_invitation','bedos_revoke_staff_invitation')
UNION ALL SELECT 'new_setup_function_count',to_jsonb(count(*)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='bedos_setup_staff_invitation';
COMMIT;
